// Obtener datos del mensaje de Telegram
const telegramData = $input.item.json.message;
const userId = telegramData.from.id;
const messageText = telegramData.text || '';
const timestamp = Date.now();

// Intentar obtener buffer existente de Redis
let buffer = null;
try {
  const redisNode = $('Redis - Get Existing Buffer');
  if (redisNode && redisNode.item && redisNode.item.json) {
    const redisResult = redisNode.item.json;
    // Redis devuelve el valor directamente como string
    if (redisResult && typeof redisResult === 'string') {
      buffer = JSON.parse(redisResult);
    }
  }
} catch (error) {
  // Si hay error parseando o no existe, buffer queda null
  console.log('No existing buffer or parse error:', error.message);
}

// Si no existe buffer, crear uno nuevo
if (!buffer) {
  buffer = {
    messages: [],
    first_message_time: timestamp,
    user_id: userId,
    chat_id: telegramData.chat.id,
    first_name: telegramData.from.first_name || 'Usuario'
  };
}

// Agregar el nuevo mensaje al array de mensajes
buffer.messages.push({
  text: messageText,
  timestamp: timestamp,
  message_id: telegramData.message_id
});

// Actualizar metadata del buffer
buffer.last_updated = timestamp;
buffer.message_count = buffer.messages.length;

// Determinar si es el primer mensaje (para activar el timer)
const isFirstMessage = buffer.messages.length === 1;

// Retornar datos para el siguiente nodo
return {
  json: {
    buffer: buffer,
    user_id: userId,
    is_first_message: isFirstMessage,
    // Debug info (opcional)
    debug: {
      message_count: buffer.messages.length,
      time_span_ms: timestamp - buffer.first_message_time
    }
  }
};
